# 1) queries: heavy views read from cache tables (fallback live if empty)
def q(s):
    s=s.replace('  stock_dashboard: { sql: "select * from v_stock_dashboard where farm_id=$1 order by block,','  stock_dashboard: { sql: "select * from cache_stock_dashboard where farm_id=$1 order by block,',1)
    s=s.replace('  herd_forecast_series: { sql: "select h.horizon, f.* from (values (0),(30),(60),(90)) h(horizon), lateral herd_forecast($1, h.horizon) f order by f.class_code, h.horizon" },','  herd_forecast_series: { sql: "select x.* from cache_kv k, jsonb_to_recordset(k.payload) as x(horizon int, class_code text, class_name text, head_now numeric, head_forecast numeric, births numeric, exits numeric) where k.farm_id=$1 and k.key=\'herd_forecast_series\' order by class_code, horizon", cache: true },',1)
    s=s.replace('  feed_forecast_series: { sql: "select h.horizon, sum(f.kg_day_forecast) as kg_day, sum(f.head_forecast) as head from (values (0),(30),(60),(90)) h(horizon), lateral feed_forecast($1, h.horizon) f group by h.horizon order by h.horizon" },','  feed_forecast_series: { sql: "select x.* from cache_kv k, jsonb_to_recordset(k.payload) as x(horizon int, kg_day numeric, head numeric) where k.farm_id=$1 and k.key=\'feed_forecast_series\' order by horizon", cache: true },',1)
    s=s.replace('  warehouse_fill: { sql: "select * from v_warehouse_fill where farm_id=$1 order by block, code" },','  warehouse_fill: { sql: "select x.* from cache_kv k, jsonb_to_recordset(k.payload) as x(farm_id text, warehouse_id text, code text, name text, block text, area text, unit_kind text, capacity numeric, qty numeric, pct_full numeric, skus int, bins int) where k.farm_id=$1 and k.key=\'warehouse_fill\' order by block, code", cache: true },',1)
    s=s.replace('export const QUERIES: Record<string, { sql: string; params?: string[] }> = {','export const QUERIES: Record<string, { sql: string; params?: string[]; cache?: boolean; ttl?: number }> = {\n  cache_status: { sql: "select farm_id, refreshed_at, (select dirty_at from cache_dirty d where d.farm_id=$1) as dirty_at from cache_kv where farm_id=$1 and key=\'warehouse_fill\'" },',1)
